-- -----------------------------------------------------
-- procedure AltaClientes
-- -----------------------------------------------------

DELIMITER $$
USE `boutique2`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `AltaClientes`(
  IN NombreCli VARCHAR(45),
  IN ApellidoCli VARCHAR(50),
  IN DireccionCli VARCHAR(60),
  IN EstadoCli ENUM('Activo', 'Inactivo'),
  IN TelefonoCli1 VARCHAR(10),
  IN TelefonoCli2 VARCHAR(10),
  IN CorreoCli1 VARCHAR(45),
  IN CorreoCli2 VARCHAR(45)
)
BEGIN
  INSERT INTO clientes (
    NombreCli, ApellidoCli, DireccionCli, EstadoCli,
    TelefonoCli1, TelefonoCli2, CorreoCli1, CorreoCli2
  ) VALUES (
    NombreCli, ApellidoCli, DireccionCli, EstadoCli,
    TelefonoCli1, TelefonoCli2, CorreoCli1, CorreoCli2
  );
END$$

