-- -----------------------------------------------------
-- procedure AltaProductos
-- -----------------------------------------------------

DELIMITER $$
USE `boutique2`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `AltaProductos`( IN nombre VARCHAR(45),
    IN descripcion VARCHAR(80),
    IN precio_compra DECIMAL(10,2),
    IN stock INT
)
BEGIN
	DECLARE precio_venta DECIMAL(10,2);
    DECLARE producto_id INT;

    -- Calcular precio de venta
    SET precio_venta = ROUND(precio_compra * 1.25, 2);

    -- Insertar el nuevo producto
    INSERT INTO productos (Nombre, Descripcion, Precio, Precio_Compra, Stock)
    VALUES (nombre, descripcion, precio_venta, precio_compra, stock);

    -- Obtener el ID del producto insertado
    SET producto_id = LAST_INSERT_ID();

    -- Registrar la entrada en el historial de compras
    INSERT INTO entrada_productos (Fecha, Producto_Id, Cantidad, Precio_Compra)
    VALUES (CURRENT_DATE, producto_id, stock, precio_compra);


END$$

DELIMITER ;

