-- -----------------------------------------------------
-- procedure AñadirStock
-- -----------------------------------------------------

DELIMITER $$
USE `boutique2`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `AñadirStock`(
    IN p_producto_id INT,
    IN p_cantidad INT,
    IN p_precio_compra DECIMAL(10,2)
)
BEGIN
  DECLARE nuevo_precio_venta DECIMAL(10,2);

    -- Calcular el precio de venta con margen del 25%
    SET nuevo_precio_venta = ROUND(p_precio_compra * 1.25, 2);

    -- Registrar la entrada de inventario
    INSERT INTO entrada_productos (Fecha, Producto_Id, Cantidad, Precio_Compra)
    VALUES (CURRENT_DATE, p_producto_id, p_cantidad, p_precio_compra);

    -- Actualizar stock y precios en productos
    UPDATE productos
    SET 
        Stock = Stock + p_cantidad,
        Precio_Compra = p_precio_compra,
        Precio = nuevo_precio_venta
    WHERE IdProductos = p_producto_id;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure RegistrarVenta
-- -----------------------------------------------------

DELIMITER $$
USE `boutique2`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `RegistrarVenta`(IN p_Fecha DATE,
    IN p_Total DECIMAL(10,2),
    IN p_IdCliente INT,
    IN p_IdEmpleado INT
)
BEGIN
DECLARE v_IdFactura INT;

    -- Insertar en la tabla de facturas (por ahora, tipo fijo: Contado)
    INSERT INTO facturas (Fecha, Total, Clientes_IdClientes, Empleados_IdEmpleados)
    VALUES (p_Fecha, p_Total, p_IdCliente, p_IdEmpleado);

    -- Obtener el ID generado automáticamente
    SET v_IdFactura = LAST_INSERT_ID();

    -- Retorna el ID si lo necesitas (opcional)
    SELECT v_IdFactura AS IdFacturaGenerada;

END$$

DELIMITER ;

-- -----------------------------------------------------
-- function comprobar_cliente_registrado
-- -----------------------------------------------------

DELIMITER $$
USE `boutique2`$$
CREATE DEFINER=`root`@`localhost` FUNCTION `comprobar_cliente_registrado`(
    id_cliente INT
) RETURNS tinyint(1)
    READS SQL DATA
BEGIN
    DECLARE cliente_existe INT;

    -- Contar cuántos clientes existen con el ID proporcionado
    SELECT COUNT(*) INTO cliente_existe 
    FROM `boutique2`.`clientes` 
    WHERE IdClientes = id_cliente;

    -- Si el conteo es mayor a 0, el cliente existe
    IF cliente_existe > 0 THEN
        RETURN TRUE;
    ELSE
        RETURN FALSE;
    END IF;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- function validar_producto_registrado
-- -----------------------------------------------------

DELIMITER $$
USE `boutique2`$$
CREATE DEFINER=`root`@`localhost` FUNCTION `validar_producto_registrado`(
    id_producto INT
) RETURNS tinyint(1)
    READS SQL DATA
BEGIN
    DECLARE producto_existe INT;

    -- Contar cuántos productos existen con el ID proporcionado
    SELECT COUNT(*) INTO producto_existe 
    FROM `boutique2`.`productos` 
    WHERE IdProductos = id_producto;

    -- Si el conteo es mayor a 0, el producto existe
    IF producto_existe > 0 THEN
        RETURN TRUE;
    ELSE
        RETURN FALSE;
    END IF;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- function verificar_stock_disponible
-- -----------------------------------------------------

DELIMITER $$
USE `boutique2`$$
CREATE DEFINER=`root`@`localhost` FUNCTION `verificar_stock_disponible`(
    id_producto INT, 
    cantidad INT
) RETURNS tinyint(1)
    READS SQL DATA
BEGIN
    DECLARE stock_actual INT;

    -- Obtener el stock actual del producto
    SELECT Stock INTO stock_actual 
    FROM `boutique2`.`productos` 
    WHERE IdProductos = id_producto;

    -- Comprobar si el stock es suficiente
    IF stock_actual >= cantidad THEN
        RETURN TRUE;
    ELSE
        RETURN FALSE;
    END IF;
END$$

