CREATE
DEFINER=`root`@`localhost`
TRIGGER `boutique2`.`disminuir_stock`
AFTER INSERT ON `boutique2`.`detalles_facturas`
FOR EACH ROW
BEGIN
    UPDATE productos SET Stock = Stock - NEW.Cantidad
    WHERE IdProductos = NEW.Productos_IdProductos;
END$$

USE `boutique2`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `boutique2`.`ActualizarEstado`
AFTER INSERT ON `boutique2`.`pagos`
FOR EACH ROW
BEGIN
  UPDATE creditos
  SET Estado = 'Liquidado'
  WHERE IdCreditos = NEW.Creditos_IdCreditos
    AND Saldo_Pendiente = 0;
END$$

USE `boutique2`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `boutique2`.`ActualizarSaldo`
AFTER INSERT ON `boutique2`.`pagos`
FOR EACH ROW
BEGIN
    UPDATE creditos
    SET Saldo_Pendiente = Saldo_Pendiente - NEW.Monto_Pagado
    WHERE IdCreditos = NEW.Creditos_IdCreditos;
END$$


